package com.mystaria.phantasmon.client.gui;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;

import com.mystaria.phantasmon.client.battle.BattleLobbyState;
import com.mystaria.phantasmon.client.battle.LiveBattleController;

/**
 * The battle lobby's format picker (2026-11-27): a window of its own over the lobby, one column of format cards per
 * kind — singles, doubles, random (teams generated by Showdown), others — each in the backend's order (National Dex
 * first, then by popularity), split into sub-groups (National Dex, Gen 9, Champions; random ones by singles /
 * doubles). A card shows the format's name and its tags (National Dex, level, Pokémon sent out, doubles, random
 * teams); a click picks it and goes back to the lobby. Each column scrolls on its own, with the wheel or by dragging
 * its scroll bar. The PC uses it too (2026-11-28), to give a team row its format: a {@link Source} says where the
 * formats come from and what a pick does.
 */
public final class PhantasmonFormatPickerScreen extends PhantasmonCanvasScreen {

	private static final String[] COLUMNS = { "SINGLES", "DOUBLES", "RANDOM", "OTHER" };
	private static final int COLUMN_Y = 72;
	private static final int COLUMN_H = 758;
	private static final int COLUMN_GAP = 10;
	private static final int COLUMN_W = (1570 - 3 * COLUMN_GAP) / 4;
	/** Cards area inside a column: under the column's title, above its bottom edge. */
	private static final int LIST_TOP = COLUMN_Y + 46;
	private static final int LIST_BOTTOM = COLUMN_Y + COLUMN_H - 10;
	private static final int LIST_H = LIST_BOTTOM - LIST_TOP;
	private static final int CARD_H = 58;
	/** A sub-group's header line, and the space above it after the previous sub-group. */
	private static final int HEADER_H = 30;
	private static final int GROUP_GAP = 8;
	private static final int TRACK_W = 6;
	private static final int CARD_GAP = 6;
	private static final int CLOSE_SIZE = 38;
	private static final int CLOSE_X = 1585 - 10 - CLOSE_SIZE;
	private static final int CLOSE_Y = 20;

	private static final int TAG_NATDEX = 0xFF2E86C1;
	private static final int TAG_CHAMPIONS = 0xFFC0392B;
	private static final int TAG_DOUBLES = 0xFF27AE60;
	private static final int TAG_RANDOM = 0xFFD4A017;
	private static final int TAG_PICK = 0xFF8E44AD;
	private static final int TAG_LEVEL = 0xFF6C7A89;

	/** Where the formats come from, which one is current, what a pick does and where the window goes back to. */
	public interface Source {
		List<BattleLobbyState.FormatOption> formats();

		/** The current format's id, or null for none. */
		String formatId();

		/** The current format's name, for the header. */
		String currentName();

		void pick(BattleLobbyState.FormatOption format);

		void back();

		/** False once the window has nothing left to do (the lobby ended, its format got locked): it goes back. */
		boolean alive();
	}

	private final Source source;
	private final int[] scroll = new int[COLUMNS.length];
	private boolean scrolledToSelection;
	/** The column whose scroll bar is being dragged (-1: none), and where in its thumb it was grabbed. */
	private int dragColumn = -1;
	private double dragOffset;

	public PhantasmonFormatPickerScreen(PhantasmonBattleLobbyScreen lobbyScreen, LiveBattleController controller) {
		this(lobbySource(lobbyScreen, controller));
	}

	public PhantasmonFormatPickerScreen(Source source) {
		super(Component.translatable("phantasmon.battle.format_picker.title"));
		this.source = source;
	}

	/** The battle lobby's format: a pick changes it (if it is another one), then back to the lobby. */
	private static Source lobbySource(PhantasmonBattleLobbyScreen lobbyScreen, LiveBattleController controller) {
		return new Source() {
			@Override
			public List<BattleLobbyState.FormatOption> formats() {
				return controller.lobby() == null ? List.of() : controller.lobby().formats();
			}

			@Override
			public String formatId() {
				return controller.lobby() == null ? null : controller.lobby().formatId();
			}

			@Override
			public String currentName() {
				return controller.lobby() == null ? "" : formatName(controller.lobby().format());
			}

			@Override
			public void pick(BattleLobbyState.FormatOption format) {
				if (controller.lobby() != null && !format.id().equals(controller.lobby().formatId())) {
					controller.lobbySetFormat(format.id());
				}
			}

			@Override
			public void back() {
				// The lobby ended (battle started, cancelled): nothing to go back to.
				net.minecraft.client.Minecraft.getInstance().setScreen(controller.lobby() != null ? lobbyScreen : null);
			}

			@Override
			public boolean alive() {
				return controller.lobby() != null && !controller.lobby().formatFixed();
			}
		};
	}

	@Override
	public void tick() {
		if (!source.alive()) {
			back();
		}
	}

	@Override
	public boolean shouldCloseOnEsc() {
		return false;
	}

	@Override
	public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
		if (keyCode == 256) {
			back();
			return true;
		}
		return super.keyPressed(keyCode, scanCode, modifiers);
	}

	private void back() {
		source.back();
	}

	// =====================================================================
	// Input
	// =====================================================================

	@Override
	public boolean mouseClicked(double mouseX, double mouseY, int button) {
		Source state = source;
		if (button != 0) {
			return super.mouseClicked(mouseX, mouseY, button);
		}
		double x = toCanvasX(mouseX);
		double y = toCanvasY(mouseY);
		if (inside(x, y, CLOSE_X, CLOSE_Y, CLOSE_SIZE, CLOSE_SIZE)) {
			back();
			return true;
		}
		int column = columnAt(x, y);
		if (column >= 0 && overflows(state, column) && inside(x, y, trackX(column) - 5, LIST_TOP, TRACK_W + 10, LIST_H)) {
			// Scroll bar: grab the thumb where it was clicked, or bring it under the cursor first.
			int[] thumb = thumb(state, column);
			if (y < thumb[0] || y >= thumb[0] + thumb[1]) {
				scrollThumbTo(state, column, y - thumb[1] / 2.0);
				thumb = thumb(state, column);
			}
			dragColumn = column;
			dragOffset = y - thumb[0];
			return true;
		}
		BattleLobbyState.FormatOption format = formatAt(state, x, y);
		if (format != null) {
			source.pick(format);
			back();
		}
		return true;
	}

	@Override
	public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
		Source state = source;
		if (dragColumn < 0) {
			return super.mouseDragged(mouseX, mouseY, button, dragX, dragY);
		}
		scrollThumbTo(state, dragColumn, toCanvasY(mouseY) - dragOffset);
		return true;
	}

	@Override
	public boolean mouseReleased(double mouseX, double mouseY, int button) {
		dragColumn = -1;
		return super.mouseReleased(mouseX, mouseY, button);
	}

	@Override
	public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY) {
		Source state = source;
		int column = columnAt(toCanvasX(mouseX), toCanvasY(mouseY));
		if (column < 0) {
			return false;
		}
		scroll[column] = clampScroll(state, column, scroll[column] - (int) Math.round(scrollY * (CARD_H + CARD_GAP)));
		return true;
	}

	/** Puts the thumb's top at {@code thumbTop} (canvas y): the column scrolls in proportion. */
	private void scrollThumbTo(Source state, int column, double thumbTop) {
		int[] thumb = thumb(state, column);
		int range = LIST_H - thumb[1];
		double ratio = range <= 0 ? 0 : (thumbTop - LIST_TOP) / range;
		int maxScroll = Math.max(0, contentHeight(layout(state, column)) - LIST_H);
		scroll[column] = clampScroll(state, column, (int) Math.round(ratio * maxScroll));
	}

	/** The scroll thumb of a column: {top, height}. */
	private int[] thumb(Source state, int column) {
		int content = contentHeight(layout(state, column));
		int thumbH = Math.max(30, LIST_H * LIST_H / Math.max(1, content));
		int thumbY = LIST_TOP + (LIST_H - thumbH) * scroll[column] / Math.max(1, content - LIST_H);
		return new int[] { thumbY, thumbH };
	}

	private static int trackX(int column) {
		return columnX(column) + COLUMN_W - 16;
	}

	private static int columnX(int column) {
		return 15 + column * (COLUMN_W + COLUMN_GAP);
	}

	private static int columnAt(double x, double y) {
		for (int c = 0; c < COLUMNS.length; c++) {
			if (inside(x, y, columnX(c), COLUMN_Y, COLUMN_W, COLUMN_H)) {
				return c;
			}
		}
		return -1;
	}

	private BattleLobbyState.FormatOption formatAt(Source state, double x, double y) {
		int column = columnAt(x, y);
		if (column < 0 || y < LIST_TOP || y >= LIST_BOTTOM) {
			return null;
		}
		int cardW = COLUMN_W - 18 - (overflows(state, column) ? TRACK_W + 8 : 0);
		for (Row row : layout(state, column)) {
			if (row.format() != null && inside(x, y, columnX(column) + 9, LIST_TOP + row.y() - scroll[column], cardW, CARD_H)) {
				return row.format();
			}
		}
		return null;
	}

	// ---- Layout: sub-groups (National Dex, Gen 9, Champions...) in each column ----

	/** A line of a column: a sub-group header ({@code headerKey}) or a card, {@code y} from the list's top. */
	private record Row(String headerKey, BattleLobbyState.FormatOption format, int y) {
	}

	/** Sub-groups, in their order in every column. */
	private static final List<String> GROUPS = List.of("free", "natdex", "gen9", "champions", "singles", "doubles");

	/**
	 * A format's sub-group: "Libre" alone; random formats by singles / doubles; otherwise Champions, National Dex or
	 * Gen 9.
	 */
	private static String group(BattleLobbyState.FormatOption format) {
		if ("free".equals(format.id())) {
			return "free";
		}
		if ("RANDOM".equals(format.column())) {
			return format.doubles() ? "doubles" : "singles";
		}
		return format.champions() ? "champions" : format.natDex() ? "natdex" : "gen9";
	}

	private static List<Row> layout(Source state, int column) {
		List<BattleLobbyState.FormatOption> formats = column(state, column);
		List<Row> rows = new ArrayList<>();
		int y = 0;
		for (String group : GROUPS) {
			boolean header = false;
			for (BattleLobbyState.FormatOption format : formats) {
				if (!group.equals(group(format))) {
					continue;
				}
				if (!header) {
					header = true;
					if (y > 0) {
						y += GROUP_GAP;
					}
					rows.add(new Row("phantasmon.battle.format_picker.group." + group, null, y));
					y += HEADER_H;
				}
				rows.add(new Row(null, format, y));
				y += CARD_H + CARD_GAP;
			}
		}
		return rows;
	}

	private static int contentHeight(List<Row> rows) {
		if (rows.isEmpty()) {
			return 0;
		}
		Row last = rows.get(rows.size() - 1);
		return last.y() + (last.format() != null ? CARD_H : HEADER_H);
	}

	private boolean overflows(Source state, int column) {
		return contentHeight(layout(state, column)) > LIST_H;
	}

	private int clampScroll(Source state, int column, int value) {
		return Math.max(0, Math.min(value, Math.max(0, contentHeight(layout(state, column)) - LIST_H)));
	}

	private static List<BattleLobbyState.FormatOption> column(Source state, int column) {
		List<BattleLobbyState.FormatOption> formats = new ArrayList<>();
		for (BattleLobbyState.FormatOption format : state.formats()) {
			if (COLUMNS[column].equals(format.column())) {
				formats.add(format);
			}
		}
		return formats;
	}

	// =====================================================================
	// Rendering
	// =====================================================================

	@Override
	public void render(GuiGraphics graphics, int mouseX, int mouseY, float partialTick) {
		Source state = source;
		renderWorldBackdrop(graphics, mouseX, mouseY, partialTick);
		if (!scrolledToSelection) {
			// Opened on a format far down a column: that column starts on it.
			scrolledToSelection = true;
			for (int c = 0; c < COLUMNS.length; c++) {
				for (Row row : layout(state, c)) {
					if (row.format() != null && row.format().id().equals(state.formatId())) {
						scroll[c] = clampScroll(state, c, row.y() - LIST_H / 2);
					}
				}
			}
		}
		double mx = toCanvasX(mouseX);
		double my = toCanvasY(mouseY);
		beginCanvas(graphics);
		renderRootPanel(graphics);
		renderHeaderPlates(graphics);
		drawText(graphics, upper(Component.translatable("phantasmon.battle.format_picker.title").getString()), 31, 32, 2f, WHITE, true, 1.5f);
		String current = Component.translatable("phantasmon.battle.format_picker.current", state.currentName()).getString();
		float currentWidth = Math.min(textWidth(current, 2f, false, 0f), 600);
		drawText(graphics, fitText(current, 600, 2f, false, 0f), CLOSE_X - 16 - currentWidth, 32, 2f, CYAN, false, 0f);
		renderCloseButton(graphics, CLOSE_X, CLOSE_Y, CLOSE_SIZE, inside(mx, my, CLOSE_X, CLOSE_Y, CLOSE_SIZE, CLOSE_SIZE));
		BattleLobbyState.FormatOption hovered = dragColumn >= 0 ? null : formatAt(state, mx, my);
		for (int c = 0; c < COLUMNS.length; c++) {
			renderColumn(graphics, state, c, hovered, mx, my);
		}
		renderFooterHints(graphics, Component.translatable("phantasmon.battle.format_picker.hints").getString(), 1546);
		endCanvas(graphics);
	}

	private void renderColumn(GuiGraphics g, Source state, int column, BattleLobbyState.FormatOption hovered,
			double mx, double my) {
		int x = columnX(column);
		List<Row> rows = layout(state, column);
		String key = "phantasmon.battle.format_picker.column." + COLUMNS[column].toLowerCase(Locale.ROOT);
		renderRailFrame(g, x, COLUMN_Y, COLUMN_W, COLUMN_H, Component.translatable(key).getString() + "  ·  "
				+ column(state, column).size(), null);
		boolean overflow = contentHeight(rows) > LIST_H;
		int cardW = COLUMN_W - 18 - (overflow ? TRACK_W + 8 : 0);
		enableCanvasScissor(g, x, LIST_TOP, COLUMN_W, LIST_H);
		for (Row row : rows) {
			int y = LIST_TOP + row.y() - scroll[column];
			if (y + CARD_H < LIST_TOP || y > LIST_BOTTOM) {
				continue;
			}
			if (row.format() == null) {
				// Sub-group header: its name in the accent colour over a thin line.
				drawText(g, upper(Component.translatable(row.headerKey()).getString()), x + 11, y + 8, 1f, CYAN, true, 1.5f);
				g.fill(x + 9, y + HEADER_H - 6, x + 9 + cardW, y + HEADER_H - 5, LINE_30);
				continue;
			}
			BattleLobbyState.FormatOption format = row.format();
			renderCard(g, format, x + 9, y, cardW, format.id().equals(state.formatId()), format.equals(hovered));
		}
		g.disableScissor();
		if (overflow) {
			// Scroll bar: the track, and the thumb for the visible part (dragged with the mouse, or the wheel).
			int trackX = trackX(column);
			g.fill(trackX, LIST_TOP, trackX + TRACK_W, LIST_BOTTOM, LINE_20);
			int[] thumb = thumb(state, column);
			boolean hot = dragColumn == column || inside(mx, my, trackX - 5, thumb[0], TRACK_W + 10, thumb[1]);
			g.fill(trackX, thumb[0], trackX + TRACK_W, thumb[0] + thumb[1], hot ? WHITE : CYAN);
		}
	}

	private void renderCard(GuiGraphics g, BattleLobbyState.FormatOption format, int x, int y, int w, boolean selected,
			boolean hovered) {
		blackBorder(g, x, y, w, CARD_H, palette().black());
		g.fill(x, y, x + w, y + CARD_H, selected ? SLOT_SELECTED_BG : hovered ? SLOT_HOVER_BG : SLOT_BG);
		raisedEdge(g, x, y, w, CARD_H);
		if (selected) {
			outline(g, x, y, w, CARD_H, CYAN);
		}
		String name = (selected ? "✔ " : "") + formatName(format);
		drawText(g, fitText(name, w - 20, 2f, false, 0f), x + 10, y + 8, 2f, selected ? READY_TEXT : WHITE, false, 0f);
		float tagX = x + 10;
		float tagY = y + 31;
		for (Tag tag : tags(format)) {
			if (tagX + badgeWidth(tag.label(), 1f) > x + w - 8) {
				break;
			}
			tagX += drawBadge(g, tag.label(), tag.color(), tagX, tagY, 1f) + 5;
		}
	}

	private record Tag(String label, int color) {
	}

	private static List<Tag> tags(BattleLobbyState.FormatOption format) {
		List<Tag> tags = new ArrayList<>();
		if ("free".equals(format.id())) {
			tags.add(new Tag(Component.translatable("phantasmon.battle.format_picker.tag.free").getString(), TAG_LEVEL));
			return tags;
		}
		if (format.natDex()) {
			tags.add(new Tag("NatDex", TAG_NATDEX));
		}
		if (format.champions()) {
			tags.add(new Tag("Champions", TAG_CHAMPIONS));
		}
		if (format.doubles() && !"DOUBLES".equals(format.column())) {
			tags.add(new Tag(Component.translatable("phantasmon.battle.format_picker.tag.doubles").getString(), TAG_DOUBLES));
		}
		if (format.randomTeam()) {
			tags.add(new Tag(Component.translatable("phantasmon.battle.format_picker.tag.random").getString(), TAG_RANDOM));
		}
		if (format.pickedTeamSize() > 0) {
			tags.add(new Tag(Component.translatable("phantasmon.battle.format_picker.tag.pick", format.pickedTeamSize(),
					format.maxTeamSize()).getString(), TAG_PICK));
		}
		if (format.adjustLevel() > 0) {
			tags.add(new Tag(Component.translatable("phantasmon.battle.format_picker.tag.level", format.adjustLevel()).getString(),
					TAG_LEVEL));
		}
		return tags;
	}

	/** Showdown's name without its "[Gen 9]" prefix ("[Gen 9 Champions] OU": "Champions OU"); "Libre" translated. */
	static String formatName(BattleLobbyState.FormatOption format) {
		if ("free".equals(format.id())) {
			return Component.translatable("phantasmon.battle.lobby.format.free").getString();
		}
		return format.name().replace("[Gen 9 Champions] ", "Champions ").replace("[Gen 9] ", "");
	}
}
